    struct nlattr *link_attr;
    struct nlattr *tb[TIPC_NLA_MAX + 1];

    if (!attrs || !msg)
        return -EINVAL;

    link_attr = attrs[TIPC_NLA_LINK];
    if (!link_attr)
        return -EINVAL;

    if (nla_parse(tb, TIPC_NLA_MAX, nla_data(link_attr), nla_len(link_attr), NULL))
