    msg->dest = nla_get_u32(tb[TIPC_NLA_LINK_DEST]);
    msg->status = nla_get_u32(tb[TIPC_NLA_LINK_STATUS]);

    if (nla_len(tb[TIPC_NLA_LINK_NAME]) >= TIPC_MAX_LINK_NAME)
